ALTER TABLE public.tournament_matches ADD COLUMN leg_winners jsonb, ADD COLUMN live_leg_winners jsonb;
COMMENT ON COLUMN public.tournament_matches.leg_winners IS 'Ordered leg winners ("a"/"b") for best-of-3 matches.';
COMMENT ON COLUMN public.tournament_matches.live_leg_winners IS 'Provisional ordered leg winners while the match is being played.';

CREATE FUNCTION public.commit_tournament_result(_actor uuid,_match_id uuid,_code text,_score_a integer,_score_b integer,_legs_a integer,_legs_b integer,_finals jsonb,_leg_winners jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.tournament_matches; t public.tournaments; manager boolean; next_match public.tournament_matches; winner_id uuid; loser_id uuid; max_round integer; BEGIN SELECT * INTO m FROM public.tournament_matches WHERE id=_match_id; SELECT * INTO t FROM public.tournaments WHERE id=m.tournament_id FOR UPDATE; SELECT * INTO m FROM public.tournament_matches WHERE id=_match_id FOR UPDATE; manager:=public.actor_manages_tournament(_actor,m.tournament_id); IF NOT manager THEN IF t.status<>'started' OR NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=t.organization_id AND status='active') OR NOT EXISTS(SELECT 1 FROM public.tournament_settings_codes WHERE tournament_id=t.id AND code=_code) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF m.winner IS NOT NULL THEN RAISE EXCEPTION 'Result already recorded'; END IF; END IF; IF m.team_a IS NULL OR m.team_b IS NULL OR _score_a<0 OR _score_b<0 OR _score_a=_score_b THEN RAISE EXCEPTION 'Invalid result'; END IF; IF m.stage<>'pool' AND NOT ((_legs_a=2 AND _legs_b IN (0,1) AND _score_a<_score_b) OR (_legs_b=2 AND _legs_a IN (0,1) AND _score_b<_score_a)) THEN RAISE EXCEPTION 'Two winning legs required'; END IF; IF _leg_winners IS NOT NULL AND NOT (jsonb_typeof(_leg_winners)='array' AND (SELECT count(*) FROM jsonb_array_elements_text(_leg_winners) w WHERE w NOT IN ('a','b'))=0 AND jsonb_array_length(_leg_winners)=coalesce(_legs_a,0)+coalesce(_legs_b,0) AND (SELECT count(*) FROM jsonb_array_elements_text(_leg_winners) w WHERE w='a')=coalesce(_legs_a,0) AND (SELECT count(*) FROM jsonb_array_elements_text(_leg_winners) w WHERE w='b')=coalesce(_legs_b,0)) THEN RAISE EXCEPTION 'Invalid leg winners'; END IF; winner_id:=CASE WHEN _score_a<_score_b THEN m.team_a ELSE m.team_b END; loser_id:=CASE WHEN winner_id=m.team_a THEN m.team_b ELSE m.team_a END; IF m.winner IS NOT NULL AND m.winner IS DISTINCT FROM winner_id AND EXISTS(SELECT 1 FROM public.tournament_matches WHERE tournament_id=t.id AND stage<>'pool' AND id<>m.id AND (winner IS NOT NULL OR live_legs_a>0 OR live_legs_b>0) AND (team_a=m.winner OR team_b=m.winner OR team_a=loser_id OR team_b=loser_id)) THEN RAISE EXCEPTION 'Dependent matches have started; correction requires review'; END IF; IF m.stage='pool' AND m.winner IS NOT NULL AND EXISTS(SELECT 1 FROM public.tournament_matches WHERE tournament_id=t.id AND stage<>'pool') THEN RAISE EXCEPTION 'Pool ranking is locked after finals generation'; END IF; UPDATE public.tournament_matches SET score_a=_score_a,score_b=_score_b,legs_a=_legs_a,legs_b=_legs_b,live_legs_a=coalesce(_legs_a,0),live_legs_b=coalesce(_legs_b,0),leg_winners=_leg_winners,live_leg_winners=_leg_winners,winner=winner_id WHERE id=m.id; IF m.stage='pool' AND NOT EXISTS(SELECT 1 FROM public.tournament_matches WHERE tournament_id=t.id AND stage='pool' AND winner IS NULL) AND NOT EXISTS(SELECT 1 FROM public.tournament_matches WHERE tournament_id=t.id AND stage<>'pool') THEN IF _finals IS NULL OR jsonb_array_length(_finals)=0 THEN RAISE EXCEPTION 'Final drafts required; retry from current snapshot'; END IF; INSERT INTO public.tournament_matches(tournament_id,stage,pool_index,round,position,team_a,team_b,winner) SELECT t.id,x.stage,x.pool_index,x.round,x.position,x.team_a,x.team_b,x.winner FROM jsonb_to_recordset(_finals) AS x(stage text,pool_index integer,round integer,position integer,team_a uuid,team_b uuid,winner uuid); END IF; IF m.stage IN ('bracket','consolation') THEN SELECT * INTO next_match FROM public.tournament_matches WHERE tournament_id=t.id AND stage=m.stage AND round=m.round+1 AND position=m.position/2; IF next_match.id IS NOT NULL THEN IF m.position%2=0 THEN UPDATE public.tournament_matches SET team_a=winner_id WHERE id=next_match.id; ELSE UPDATE public.tournament_matches SET team_b=winner_id WHERE id=next_match.id; END IF; ELSIF m.stage='bracket' THEN UPDATE public.tournaments SET status='finished' WHERE id=t.id; END IF; IF m.stage='bracket' THEN SELECT max(round) INTO max_round FROM public.tournament_matches WHERE tournament_id=t.id AND stage='bracket'; IF m.round=max_round-1 THEN IF m.position%2=0 THEN UPDATE public.tournament_matches SET team_a=loser_id WHERE tournament_id=t.id AND stage='small_final'; ELSE UPDATE public.tournament_matches SET team_b=loser_id WHERE tournament_id=t.id AND stage='small_final'; END IF; END IF; END IF; END IF; UPDATE public.tournaments SET revision=revision+1 WHERE id=t.id; INSERT INTO public.organization_audit_events(organization_id,actor_id,action,details) VALUES(t.organization_id,_actor,CASE WHEN m.winner IS NULL THEN 'tournament.result_recorded' ELSE 'tournament.result_corrected' END,jsonb_build_object('match_id',m.id)); INSERT INTO public.notifications(recipient_id,organization_id,kind,payload) SELECT DISTINCT captain_id,t.organization_id,'tournament.result',jsonb_build_object('tournament_id',t.id,'match_id',m.id) FROM public.tournament_teams WHERE id IN(m.team_a,m.team_b) AND captain_id IS NOT NULL; END $$;
REVOKE ALL ON FUNCTION public.commit_tournament_result(uuid,uuid,text,integer,integer,integer,integer,jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.commit_tournament_result(uuid,uuid,text,integer,integer,integer,integer,jsonb,jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.commit_tournament_result(_actor uuid,_match_id uuid,_code text,_score_a integer,_score_b integer,_legs_a integer,_legs_b integer,_finals jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.commit_tournament_result(_actor,_match_id,_code,_score_a,_score_b,_legs_a,_legs_b,_finals,NULL::jsonb); END $$;
REVOKE ALL ON FUNCTION public.commit_tournament_result(uuid,uuid,text,integer,integer,integer,integer,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.commit_tournament_result(uuid,uuid,text,integer,integer,integer,integer,jsonb) TO service_role;